mapper.select:
SELECT game_id, min_level, max_level
FROM public.game_level_configs
WHERE game_id = #{gameId}

SELECT game_id, character_key, name, description, created_at, updated_at FROM public.characters WHERE game_id = #{gameId}
AND ( strpos(lower(character_key), lower(#{keyword})) > 0 OR strpos(lower(name), lower(#{keyword})) > 0 )
ORDER BY name ASC, character_key ASC

SELECT game_id, character_key, name, description, created_at, updated_at
FROM public.characters
WHERE game_id = #{gameId} AND character_key = #{characterKey}

SELECT COUNT(1) FROM public.characters
WHERE game_id = #{gameId} AND lower(btrim(name)) = lower(btrim(#{name}))

    AND character_key <> #{excludeCharacterKey}

mapper.update:
UPDATE public.characters
SET name = #{name}, description = #{description}, updated_at = now()
WHERE game_id = #{gameId} AND character_key = #{characterKey}

mapper.select:
SELECT level_values::text
FROM public.character_attributes
WHERE game_id = #{gameId} AND character_key = #{characterKey}

mapper.update:
UPDATE public.character_attributes
SET level_values = CAST(#{levelValuesJson} AS jsonb), updated_at = now()
WHERE game_id = #{gameId} AND character_key = #{characterKey}
